/**
 * 手机端抓取脚本（免电脑，零费用）
 *
 * ---------------------------------------------------------------------------
 * 这是什么
 * ---------------------------------------------------------------------------
 * 原流程要在电脑上跑抓取脚本（浏览器 + CDP），才能把学习通作业搬进小程序。
 * 这个文件把那段采集逻辑打包成一段**可以在手机浏览器里直接执行**的脚本：
 *
 *   手机浏览器打开学习通作业页 → 点一下书签执行脚本 → 脚本把整份作业
 *   转成小程序能吃的 JSON 并复制到剪贴板 → 回到小程序「粘贴导入」粘贴即可。
 *
 * 不需要云函数、不需要 Key、不需要花钱 —— 解析全在你手机浏览器本地完成。
 *
 * ---------------------------------------------------------------------------
 * 两个产物
 * ---------------------------------------------------------------------------
 *   BOOKMARKLET   完整的手机脚本源码（`javascript:` 开头的一整段），由
 *                 tools/build-grab-script.js 生成后写回本文件的标记区间内。
 *                 别手改它 —— 改了也会被下次构建覆盖。要改就改源头
 *                 （采集端 parser）或下面的 capToAssignment，然后重新构建。
 *   capToAssignment  采集结果 → 小程序导入包的格式转换。纯函数：不碰 DOM、
 *                 不碰 wx，所以 Node 里能直接单测，浏览器里也能直接跑。
 *
 * 用法见 STEPS（导入页会照着它渲染操作指引）。
 */

/* ---------------- 格式转换（纯函数，可单测） ---------------- */

/** 题型白名单：与 pages/import 的 typeOptions 一致，认不出的回落解答题 */
var TYPES = ['解答题', '证明题', '计算题', '选择题', '填空题', '判断题'];

/** 判定归一：学习通的 unmarked（未批改）在小程序里记作 unknown */
var VERDICT_MAP = {
  correct: 'correct',
  wrong: 'wrong',
  partial: 'partial',
  unmarked: 'unknown',
  unknown: 'unknown'
};

/** 纯文本 → 单节点数组（没有现成 nodes 时的兜底） */
function textNodes(text) {
  var t = String(text || '').trim();
  return t ? [{ t: 't', v: t }] : [];
}

/**
 * 取富文本节点：**优先用采集端原样搬过来的 nodes**，没有才退回纯文本。
 *
 * 这是「全量搬运」的关键一步。采集端（parser.js 的 nodesFrom）已经把页面上的
 * 文字、公式图、手写照片按原位顺序摊平成了 {t:'t'|'i'|'br'} 序列 —— 直接用，
 * 就等于把页面原封不动搬进小程序；退回 textNodes 只在老页面/兜底路径才发生。
 *
 * 图片节点的两个标记，决定小程序怎么渲染（见 templates/nodes.wxml）：
 *   p = 1  → 手写照片 / 普通插图，widthFix 等比缩放
 *   f = 1  → 行内公式图，按 w/h 的 rpx 固定尺寸渲染（与正文字号齐平）
 *
 * @param {Array} nodes    采集端来的节点
 * @param {string} fallbackText  没有 nodes 时的纯文本兜底
 */
function pickNodes(nodes, fallbackText) {
  if (nodes && nodes.length) {
    var out = [];
    nodes.forEach(function (n) {
      if (!n || !n.t) return;
      if (n.t === 't') {
        var v = String(n.v == null ? '' : n.v);
        if (!v) return;
        out.push({ t: 't', v: v });
        return;
      }
      if (n.t === 'i') {
        if (!n.s) return;
        var im = { t: 'i', s: String(n.s) };
        if (n.f) {
          im.f = 1;
          // 公式图必须有尺寸，否则小程序里会塌成一个点；采集端估过就沿用
          im.w = n.w || 60;
          im.h = n.h || 30;
        } else {
          im.p = 1;                      // 照片：交给 widthFix
          im.w = n.w || 0;
          im.h = n.h || 0;
        }
        out.push(im);
        return;
      }
      if (n.t === 'br') {
        // 开头/连续换行没意义，末尾的也去掉
        if (!out.length) return;
        if (out[out.length - 1].t === 'br') return;
        out.push({ t: 'br' });
      }
    });
    while (out.length && out[out.length - 1].t === 'br') out.pop();
    if (out.length) return out;
  }
  return textNodes(fallbackText);
}

/** nodes 里有没有图片（决定 photo 标记，也决定详情页要不要留「原始照片」折叠块） */
function hasImgNodes(nodes) {
  if (!nodes || !nodes.length) return false;
  for (var i = 0; i < nodes.length; i++) if (nodes[i].t === 'i') return true;
  return false;
}

/** nodes 里有没有真正的文字（用来判断「这条到底有没有内容可搬」） */
function hasTextNodes(nodes) {
  if (!nodes || !nodes.length) return false;
  for (var i = 0; i < nodes.length; i++) {
    if (nodes[i].t === 't' && String(nodes[i].v || '').trim()) return true;
  }
  return false;
}

/**
 * 采集端 extractSync() 的结果 → 小程序的作业包格式。
 *
 * 「全量搬运」在这里落地：采集端搬来的文字 + 图片 nodes 原样透传，**不做任何理解**。
 * 题干里的公式是图片就还是图片（照原样显示），手写解答是照片就还是照片；
 * 小程序侧再决定怎么用（订正、错因分析、训练）。
 *
 * @param {object} cap {title, course, questions:[...]}
 * @param {{courseId?:string, id?:string, now?:number, title?:string}} opts
 * @returns {object|null} 与 data/sample-import.js 同构；解析不出题返回 null
 */
function capToAssignment(cap, opts) {
  opts = opts || {};
  if (!cap || !Array.isArray(cap.questions)) return null;

  var qs = [];
  (cap.questions || []).forEach(function (q, i) {
    q = q || {};
    var stem = String(q.stem || '').trim();
    var my = String(q.myAnswer || '').trim();
    var right = String(q.correctAnswer || '').trim();
    var comment = String(q.teacherComment || '').trim();

    // 富文本节点：优先采集端原样搬来的（含公式图/手写照片），退回纯文本
    var stemNodes = pickNodes(q.stemNodes, stem);
    var myNodes = pickNodes(q.myAnswerNodes, my);
    var rightNodes = pickNodes(q.correctAnswerNodes, right);
    var commentNodes = pickNodes(q.commentNodes, comment);

    // 判断这一条到底「有没有东西可搬」——三样全空才丢。
    // 注意三个都数：纯文本字段、nodes 里的文字、nodes 里的图片。
    // 只数纯文本 → 手写作答（只有照片）会被误扔；
    // 只数图片 → 某些页面题干全在 nodes 里、没有 stem 字段，也会被误扔。
    var hasAny = stem || my || right || comment
      || hasTextNodes(stemNodes) || hasTextNodes(myNodes)
      || hasTextNodes(rightNodes) || hasTextNodes(commentNodes)
      || hasImgNodes(stemNodes) || hasImgNodes(myNodes)
      || hasImgNodes(rightNodes) || hasImgNodes(commentNodes)
      || (q.images && q.images.length);
    if (!hasAny) return;

    var sc = q.score || {};
    var got = (typeof sc.got === 'number' && isFinite(sc.got)) ? sc.got : null;
    var total = (typeof sc.total === 'number' && isFinite(sc.total) && sc.total > 0) ? sc.total : null;

    // gist 是列表页那一行的摘要：优先取题干的第一段文字节点
    var gistSrc = '';
    if (stem) gistSrc = stem;
    else for (var gi = 0; gi < stemNodes.length; gi++) {
      if (stemNodes[gi].t === 't') { gistSrc = stemNodes[gi].v; break; }
    }

    qs.push({
      no: (typeof q.no === 'number' && q.no > 0) ? q.no : (i + 1),
      type: TYPES.indexOf(q.type) >= 0 ? q.type : '解答题',
      score: got,
      fullScore: total || 20,
      gist: String(gistSrc || '').replace(/\s+/g, ' ').trim().slice(0, 14),
      stem: stemNodes,
      stemText: stem,
      myAnswer: { nodes: myNodes, text: my, photo: !!(q.myAnswerPhoto || hasImgNodes(myNodes)) },
      rightAnswer: { nodes: rightNodes, text: right },
      comment: { nodes: commentNodes, text: comment },
      kp: [],
      flaws: [],
      verdict: VERDICT_MAP[q.verdict] || 'unknown',
      analysisNote: ''
    });
  });

  if (!qs.length) return null;

  var gotSum = 0, fullSum = 0;
  qs.forEach(function (q) {
    if (typeof q.score === 'number') gotSum += q.score;
    fullSum += q.fullScore;
  });

  return {
    id: 'as_phone_' + (opts.now || Date.now()),
    courseId: opts.courseId || 'c_math',
    title: String(cap.title || opts.title || '学习通作业').slice(0, 60),
    fullScore: fullSum,
    score: gotSum,
    // 抓取路线是「原样搬运」：一份作业的题全都要，不按得分/判词挑。
    // 理由：学习通上大量作业根本没有教师批语（没分、没判词），按「只收错题」
    // 会把整份作业滤成 0 道 —— 而用户要的是先把内容搬进来，之后在小程序里处理。
    importAll: opts.onlyWrong ? false : true,
    questions: qs
  };
}

